window.ATLAS.addDetails("life.edges",{"edges":{
"action-potential:feedback":{"type":"connection","label":{"zh":"Na⁺ 通道的正反馈","en":"Positive feedback in the Na⁺ channels"},"reason":{"zh":"电位一升，更多电压门控 Na⁺ 通道打开，Na⁺ 进得更多、电位升得更快——这是一条正反馈，所以过了阈值就停不下来，只能冲到顶，这正是“全或无”的来源。","en":"A rise in voltage opens more voltage-gated Na⁺ channels, letting in more Na⁺ and raising the voltage faster — positive feedback, which is why once past threshold the spike cannot stop halfway: the origin of “all-or-none”."},"source":"../biology/body/action-potential/#step1"},
"alcohol-zero-order:fever-set-point":{"type":"connection","label":{"zh":"高热：出口饱和，和酒精同构","en":"Heat stroke: a saturated exit, like alcohol"},"reason":{"zh":"第 5 章用第 3 章的“封顶出口”区分两种体温升高：发烧是设定点被调高，高热是出汗已到上限、外界热负荷超过它。","en":"Chapter 5 uses chapter 3’s capped exit to separate two kinds of high temperature: fever moves the set point, while heat stroke is sweating at its limit with the heat load above it."},"source":"../biology/body/body-in-balance/#ch5"},
"base-rate-neglect:vaccinated-share-of-cases":{"type":"connection","label":{"zh":"基础比率","en":"Base rates"},"reason":{"zh":"第 5 章：病例里多数打过疫苗，是因为接种者本来就多得多，这是基础比率问题；“数字没有说谎，结论却错了”第 6 章用阳性检测讲了同一结构。","en":"Chapter 5: most cases are vaccinated because vaccinated people are far more numerous to begin with, a base-rate question; chapter 6 of Every Number Was True shows the same structure with a positive test."},"source":"../biology/body/how-vaccines-work/#ch5"},
"blood-circulation:cardiac-output-budget":{"type":"foundation","label":{"zh":"心输出量 = 心率 × 每搏量","en":"Cardiac output = heart rate × stroke volume"},"reason":{"zh":"第 7 章以血液循环的第 3、4 步为基础：心输出量等于心率乘每搏量，运动时需求上升，每搏量先到顶，余下全靠心率。","en":"Chapter 7 builds on steps 3 and 4 of Blood Circulation: cardiac output is heart rate times stroke volume; in exercise stroke volume tops out first and the rest falls on heart rate."},"source":"../biology/body/body-in-balance/#ch7"},
"cell-structure:dna-replication":{"type":"application","label":{"zh":"核里的信息要靠复制传下去","en":"The nucleus's information passes on through replication"},"reason":{"zh":"细胞核管着遗传信息，信息要进下一代就得复制——细胞页的“指挥中心”，在复制页变成“复制什么、怎么保真”。","en":"The nucleus holds the genetic information, and for it to reach the next generation it must be copied — the cell page's 'command center' becomes, on the replication page, 'what is copied and how faithfully'."},"source":"../biology/cells/cell-structure/#step1"},
"cell-structure:membrane-transport":{"type":"foundation","label":{"zh":"细胞膜是这道门","en":"The cell membrane is the gate"},"reason":{"zh":"细胞靠一层膜把内外分开；膜对不同物质的通透性不同，内外浓度才能维持差异，也才谈得上谁进谁出。","en":"A cell keeps inside and outside apart with a membrane; because the membrane lets different substances through to different degrees, inside and outside can hold different concentrations, and it makes sense to ask what goes in and what comes out."},"source":"../biology/cells/membrane-transport/"},
"cell-structure:molecules-atoms":{"type":"foundation","label":{"zh":"细胞是分子搭成的车间","en":"Cells are workshops built from molecules"},"reason":{"zh":"从叶子逐级放大到细胞，是同一条尺度链的下一级：细胞比分子大得多，里面的工位全由分子搭成。","en":"Zooming from a leaf down to a cell is the next level of the same scale chain: cells are far larger than molecules, and every workstation inside is built from them."},"source":"../biology/cells/cell-structure/#step0"},
"cell-structure:photosynthesis":{"type":"application","label":{"zh":"叶绿体是光合作用的车间","en":"The chloroplast is photosynthesis's workshop"},"reason":{"zh":"细胞页里叶绿体只是“光合的工位”，光合页讲它怎样把光变成糖——结构与功能在两页接上，植物细胞多出叶绿体正为此准备。","en":"On the cell page the chloroplast is just 'the photosynthesis workstation'; the photosynthesis page shows how it turns light into sugar — structure meets function across the two pages, and plant cells carry chloroplasts for exactly this."},"source":"../biology/cells/cell-structure/#step2"},
"drug-half-life-plateau:antibiotic-selection-window":{"type":"foundation","label":{"zh":"浓度来自第 2 章的给药模型","en":"Concentration from chapter 2’s dosing model"},"reason":{"zh":"第 8 章的抗生素浓度用第 2 章的模型算（每 8 小时一次、半衰期 4 小时）；浓度落在两种菌的最低抑菌浓度之间的时间，决定耐药菌能否胜出。","en":"Chapter 8 computes the antibiotic level with chapter 2’s model (every 8 h, half-life 4 h); the time the level spends between the two strains’ MICs decides whether resistant cells win."},"source":"../biology/body/body-in-balance/#ch8"},
"drug-half-life-plateau:therapeutic-window":{"type":"foundation","label":{"zh":"第 2 章的给药模型加上下限","en":"Chapter 2’s dosing model, with two limits"},"reason":{"zh":"第 6 章的浓度曲线就是第 2 章的给药模型；同样总剂量分成每天 3 次时峰谷都在窗内，清除变慢一倍时第 24 小时起越过上限。","en":"Chapter 6’s concentration curve is chapter 2’s dosing model; the same daily total split three ways stays inside the window, and with clearance halved it crosses the upper limit from hour 24."},"source":"../biology/body/body-in-balance/#ch6"},
"electric-fields:resting-potential":{"type":"foundation","label":{"zh":"膜两侧的电势差","en":"A potential difference across the membrane"},"reason":{"zh":"膜内外正负离子分布不均，就在薄薄一层膜两侧形成电势差；静息电位就是用伏特（毫伏）来量的这一段电势差。","en":"Unequal positive and negative ions on the two sides of a thin membrane create a potential difference across it; the resting potential is that difference, measured in volts (millivolts)."},"source":"../biology/body/neuroscience-basics/#step0"},
"enzymes:alcohol-zero-order":{"type":"foundation","label":{"zh":"酶饱和：每小时只代谢固定的量","en":"A saturated enzyme clears a fixed amount per hour"},"reason":{"zh":"第 3 章引用酶那一页的第 1 步：酒精脱氢酶在低浓度下就已饱和（Km 约 5 mg/100 mL），代谢速度近似恒定，这就是零级动力学。","en":"Chapter 3 cites step 1 of the Enzymes page: alcohol dehydrogenase saturates at low levels (Km about 5 mg/100 mL), so the clearance rate is nearly constant, which is zero-order kinetics."},"source":"../biology/body/body-in-balance/#ch3"},
"epidemic-r0:herd-immunity-threshold":{"type":"foundation","label":{"zh":"由 R₀ 推出阈值","en":"The threshold follows from R₀"},"reason":{"zh":"第 9 章把 R₀ 交给公共卫生那一页的第 0 步，只推出阈值 1 − 1/R₀：R₀ = 3 时 67%，麻疹 12–18 时 92–94%。","en":"Chapter 9 leaves R₀ to step 0 of the Public Health page and derives only the threshold 1 − 1/R₀: 67% at R₀ = 3, 92–94% for measles at 12–18."},"source":"../biology/body/body-in-balance/#ch9"},
"epidemic-r0:vaccination-coverage-needed":{"type":"foundation","label":{"zh":"R₀ 从哪里来","en":"Where R₀ comes from"},"reason":{"zh":"第 6 章的阈值 1 − 1/R₀ 用到 R₀，它由什么决定见“公共卫生”第 0 步。","en":"Chapter 6’s threshold 1 − 1/R₀ needs R₀; what sets it is step 0 of Public Health."},"source":"../biology/body/how-vaccines-work/#ch6"},
"exp-log:epidemic-r0":{"type":"foundation","label":{"zh":"一代乘一个 R","en":"Multiply by R each generation"},"reason":{"zh":"每个病例传给 R 个人，开头病例数就一代乘一次 R：R > 1 时指数增长，R < 1 时指数衰减。页面的 SIR 曲线开头正是这段指数增长，之后易感者耗尽才把它压弯。","en":"Each case passes it to R others, so early on case numbers are multiplied by R every generation: exponential growth when R > 1, exponential decay when R < 1. The page’s SIR curve starts with exactly that exponential rise, until running out of susceptibles bends it over."},"source":"../biology/body/public-health/#step0"},
"exp-log:logistic-growth":{"type":"foundation","label":{"zh":"没有 K 时就是指数增长","en":"Without K it is exponential growth"},"reason":{"zh":"N(t) = N₀·e^(rt) 是逻辑斯蒂曲线的起点：N 远小于 K 时两条线重合，翻倍时间是 ln2 / r；K 只是把这条指数线压弯。","en":"N(t) = N₀·e^(rt) is where the logistic curve starts: while N is far below K the two lines coincide and the doubling time is ln2 / r; K only bends that exponential."},"source":"../biology/ecology/logistic-growth/#step1"},
"food-web:energy-pyramid":{"type":"connection","label":{"zh":"能量逐级递减","en":"Energy shrinks level by level"},"reason":{"zh":"每上一个营养级能量只留下传递效率那一小部分，所以金字塔越往上越窄，顶级捕食者数量最少。","en":"Each trophic level up keeps only the transfer-efficiency fraction of the energy, so the pyramid narrows upward and top predators are the fewest."},"source":"../biology/ecology/food-web/#step1"},
"glucose-feedback:cardiac-output-budget":{"type":"connection","label":{"zh":"守住一个量，另一个量要摆动","en":"To hold one quantity, another swings"},"reason":{"zh":"第 7 章沿用第 4 章的反馈结构：心率随需求滞后调整，以守住供氧；守住的是氧，摆动的是心率。","en":"Chapter 7 reuses chapter 4’s feedback structure: heart rate follows demand with a lag to hold oxygen delivery; oxygen is held, heart rate swings."},"source":"../biology/body/body-in-balance/#ch7"},
"glucose-feedback:fever-set-point":{"type":"connection","label":{"zh":"负反馈守住被移动的设定点","en":"Feedback defends a moved set point"},"reason":{"zh":"第 5 章沿用第 4 章的负反馈：体温被推开后会被拉回设定点；发烧时设定点本身上移，所以人在 38 度时还觉得冷。","en":"Chapter 5 reuses chapter 4’s negative feedback: a pushed temperature is pulled back to its set point; in a fever the set point itself moves up, so at 38 degrees one still feels cold."},"source":"../biology/body/body-in-balance/#ch5"},
"herd-immunity-threshold:vaccination-coverage-needed":{"type":"foundation","label":{"zh":"再除以效力","en":"Then divide by efficacy"},"reason":{"zh":"“身体是怎么稳住的”第 9 章用 1,200 人的格子演示了群体免疫阈值；第 6 章补上一点：疫苗不是 100% 有效，所以需要的接种率是阈值 ÷ 效力。","en":"Chapter 9 of How the Body Keeps Things Steady showed the herd immunity threshold on a grid of 1,200 people; chapter 6 adds that vaccines are not 100% effective, so the coverage needed is the threshold ÷ efficacy."},"source":"../biology/body/how-vaccines-work/#ch6"},
"logistic-growth:chaos-threebody":{"type":"connection","label":{"zh":"r 太大时离散模型走向混沌","en":"Push r too far and the discrete model turns chaotic"},"reason":{"zh":"逐代迭代 N ← N + rN(1 − N/K) 在 r > 2 时不再趋稳：先 2 周期、4 周期，r 约 2.57 以后进入混沌，初值差一点结果就天差地别——和三体一样，确定规则也能不可预测。","en":"The generation-by-generation update N ← N + rN(1 − N/K) stops settling once r > 2: first period 2, then 4, and past r ≈ 2.57 it is chaotic, with tiny differences in the start blowing up — like the three-body problem, a deterministic rule that cannot be predicted."},"source":"../biology/ecology/logistic-growth/#step4"},
"logistic-growth:predator-prey":{"type":"foundation","label":{"zh":"在 K 的反馈旁边加一个捕食者","en":"Add a predator next to the K feedback"},"reason":{"zh":"捕食者—猎物模型以猎物自己的逻辑斯蒂增长为底，再加上被吃掉的那一项；没有捕食者时，猎物就停在 K。","en":"The predator–prey model starts from the prey’s own logistic growth and adds a term for being eaten; with no predator the prey simply settles at K."},"source":"../biology/ecology/population-ecology/#step2"},
"membrane-transport:resting-potential":{"type":"foundation","label":{"zh":"离子梯度是静息电位的本钱","en":"Ion gradients are what the resting potential spends"},"reason":{"zh":"钠钾泵耗能把 K⁺ 泵进、Na⁺ 泵出，建立膜内外的离子浓度差；K⁺ 顺着浓度差从漏通道漏出，膜内就变负，这就是静息电位。","en":"The sodium–potassium pump spends energy moving K⁺ in and Na⁺ out, building concentration differences across the membrane; K⁺ leaking back out through its channels leaves the inside negative — the resting potential."},"source":"../biology/body/neuroscience-basics/#step0"},
"natural-selection:antibiotic-selection-window":{"type":"application","label":{"zh":"病人体内的自然选择","en":"Natural selection inside a patient"},"reason":{"zh":"第 8 章说抗生素浓度在“挑选”细菌：中等浓度杀死敏感菌、留下耐药菌，正是自然选择在一次疗程里的样子。","en":"Chapter 8 says the antibiotic level selects bacteria: a middling level kills sensitive cells and leaves resistant ones, natural selection within one course of treatment."},"source":"../biology/body/body-in-balance/#ch8"},
"ode-phase-portraits:predator-prey":{"type":"representation","label":{"zh":"把两条时间曲线画成一个圈","en":"Two time curves drawn as one loop"},"reason":{"zh":"以猎物数为横轴、捕食者数为纵轴，此起彼伏的两条时间曲线就成了相平面上绕平衡点的闭圈；加上拥挤项（即 K），闭圈变成向内收的螺旋。","en":"Put prey on one axis and predators on the other and the two alternating time curves become a closed loop around the equilibrium in the phase plane; add a crowding term (K) and the loop becomes an inward spiral."},"source":"../math/calculus/ode-phase-portraits/#step2"},
"particles-states:membrane-transport":{"type":"foundation","label":{"zh":"扩散来自分子的随机运动","en":"Diffusion comes from random molecular motion"},"reason":{"zh":"分子一直在乱动，单个分子往哪边跑都可能；只是浓度高的一侧分子更多，统计上穿过去的更多，净通量才顺着浓度差。","en":"Molecules are always jostling, and any single one may go either way; there are simply more on the crowded side, so statistically more cross from there, and the net flux runs down the gradient."},"source":"../biology/cells/membrane-transport/"},
"photosynthesis:carbon-cycle":{"type":"application","label":{"zh":"叶片尺度 → 全球尺度","en":"Leaf scale → global scale"},"reason":{"zh":"光合作用每年把约 120 GtC 从空气移入植物，与呼吸大致相抵，是碳循环里最大的陆地流量。","en":"Photosynthesis moves about 120 GtC a year from air into plants, roughly cancelled by respiration, the largest land flux in the carbon cycle."},"source":"../earth/climate/carbon-cycle/#step1"},
"pid-controller:glucose-feedback":{"type":"connection","label":{"zh":"增益与延迟","en":"Gain and delay"},"reason":{"zh":"第 4 章引用反馈控制的第 1 步：胰岛素反馈太弱时血糖久居高位，又强又晚时先冲高再跌到偏低，和控制器的增益与延迟是同一组取舍。","en":"Chapter 4 cites step 1 of Feedback Control: weak insulin feedback leaves glucose high, strong and late feedback overshoots into a low, the same trade-off as a controller’s gain and delay."},"source":"../biology/body/body-in-balance/#ch4"},
"predator-prey:feedback":{"type":"connection","label":{"zh":"带延迟的负反馈会振荡","en":"Negative feedback with delay oscillates"},"reason":{"zh":"捕食者把猎物压下来，是一条负反馈；但它要过一段时间才跟上猎物的变化，延迟让调节总是过头，于是数量围着平衡点起伏——和控制系统里延迟导致振荡是同一个道理。","en":"Predators pushing prey down is negative feedback, but they respond only after a lag, so the correction always overshoots and numbers swing around the balance point — the same reason delay makes a control loop oscillate."},"source":"../biology/ecology/population-ecology/#step2"},
"primary-immune-response:secondary-response-memory-cells":{"type":"foundation","label":{"zh":"同一个免疫模型","en":"The same immune model"},"reason":{"zh":"第 2 章用第 1 章的同一组方程，把疫苗当作抗原脉冲：第一针留下的记忆细胞让第二次应答从更高处起步，峰值高 6.9 倍。","en":"Chapter 2 runs chapter 1’s equations with the vaccine as an antigen pulse: memory cells left by dose 1 make the second response start higher, with a peak 6.9× larger."},"source":"../biology/body/how-vaccines-work/#ch2"},
"relative-vs-absolute-risk:vaccine-efficacy-relative-risk":{"type":"connection","label":{"zh":"相对风险与绝对风险","en":"Relative and absolute risk"},"reason":{"zh":"第 4 章说一个效力数字漏掉了绝对风险：试验里每 10,000 人只少病约 84 例，约 119 人接种防一例；两者的区别见“数字没有说谎，结论却错了”第 7 章。","en":"Chapter 4 notes that one efficacy number leaves out absolute risk: the trial prevented about 84 cases per 10,000, about 119 vaccinated per case prevented; the difference is chapter 7 of Every Number Was True."},"source":"../biology/body/how-vaccines-work/#ch4"},
"resting-potential:action-potential":{"type":"foundation","label":{"zh":"从 −70 mV 出发","en":"Starting from −70 mV"},"reason":{"zh":"每个尖峰都从静息电位起跳、最后落回它附近；阈值也是相对静息电位而言，要推高十几毫伏才会触发。","en":"Every spike takes off from the resting potential and falls back near it; the threshold, too, is measured from rest — the voltage has to be pushed up by a dozen or so millivolts to trigger it."},"source":"../biology/body/action-potential/#step0"},
"secondary-response-memory-cells:infection-vs-severe-disease":{"type":"foundation","label":{"zh":"两针之后碰到病毒","en":"Meeting the virus after two doses"},"reason":{"zh":"第 3 章在第 2 章的两针之后放入病毒：抗体高于“门槛”就当场挡住，抗体消退后靠记忆细胞追赶，防重症比防感染持久。","en":"Chapter 3 introduces the virus after chapter 2’s two doses: antibody above the door level stops it at once; once antibody wanes, memory cells chase it, so protection against severe disease outlasts protection against infection."},"source":"../biology/body/how-vaccines-work/#ch3"},
"steady-state-set-point:alcohol-zero-order":{"type":"connection","label":{"zh":"出口有上限的桶","en":"A bucket whose exit has a cap"},"reason":{"zh":"第 3 章把酒精写成第 1 章的桶，只是出口被酶饱和封顶：每小时只出固定的量，进得比它快就没有平台。","en":"Chapter 3 writes alcohol as chapter 1’s bucket with an exit capped by a saturated enzyme: a fixed amount leaves per hour, so intake faster than that has no plateau."},"source":"../biology/body/body-in-balance/#ch3"},
"steady-state-set-point:drug-half-life-plateau":{"type":"foundation","label":{"zh":"差距每 ln2/k 减半就是半衰期","en":"The gap halves every ln2/k: the half-life"},"reason":{"zh":"第 1 章漏水桶的差距每 ln2/k 减半；第 2 章不需要新概念，这个时间就是药物的半衰期，反复给药在约 5 个半衰期后到达平台（97%）。","en":"In chapter 1 the leaky bucket’s gap halves every ln2/k; chapter 2 needs no new idea, because that time is the drug’s half-life, and repeated doses reach a plateau after about five half-lives (97%)."},"source":"../biology/body/body-in-balance/#ch2"},
"steady-state-set-point:herd-immunity-threshold":{"type":"connection","label":{"zh":"人群尺度的进出平衡","en":"In and out balance at population scale"},"reason":{"zh":"第 9 章把第 1 章的进出平衡放到人群上：每个病例传出的新病例少于 1（Re < 1）时疫情自己消退；阈值是 1 − 1/R₀。","en":"Chapter 9 moves chapter 1’s in/out balance to a population: when each case passes on fewer than one new case (Re < 1) an outbreak dies out; the threshold is 1 − 1/R₀."},"source":"../biology/body/body-in-balance/#ch9"},
"vaccination-coverage-needed:waning-immunity-boosters":{"type":"foundation","label":{"zh":"阈值要一直守住","en":"The threshold has to be held"},"reason":{"zh":"第 7 章用第 6 章的阈值 1 − 1/R₀：保护随时间消退，有效再生数会重新升过 1，所以阈值要靠加强针守住，而不是跨过一次就够。","en":"Chapter 7 uses chapter 6’s threshold 1 − 1/R₀: protection wanes, the effective reproduction number climbs back above 1, so the threshold has to be held with boosters rather than crossed once."},"source":"../biology/body/how-vaccines-work/#ch7"},
"vaccine-efficacy-relative-risk:vaccinated-share-of-cases":{"type":"foundation","label":{"zh":"用第 4 章的效力","en":"Using chapter 4’s efficacy"},"reason":{"zh":"第 5 章用第 4 章定义的效力 e 算病例里接种者的比例 c(1−e)/(c(1−e)+1−c)；接种率超过 1/(2−e) 后，病例多数打过疫苗。","en":"Chapter 5 uses chapter 4’s efficacy e to compute the vaccinated share of cases, c(1−e)/(c(1−e)+1−c); above coverage 1/(2−e) most cases are vaccinated."},"source":"../biology/body/how-vaccines-work/#ch5"},
"working-memory-attention:signal-detection-theory":{"type":"connection","label":{"zh":"目标是信号，干扰物与它争道","en":"Targets are signal, distractors compete"},"reason":{"zh":"本页把注意当作带宽有限的通道：目标是要找的信号，干扰物同时涌入，干扰越多命中率越低。信号检测论是继续读这类任务的标准方法：它把“分不分得开”（d′）与“多愿意说有”（判据 c）分开，本页的模型只画出前一种方向。","en":"The page treats attention as a limited channel: targets are the signal you look for, distractors arrive alongside them, and hits fall as distractors rise. Signal detection theory is the standard way to read such a task further: it separates how well targets can be told apart (d′) from how readily one says “yes” (criterion c); the page models only the first."},"source":"../psychology/cognition/memory-attention/#step1"}
}});
